  $workers=[];for($i=0;$i<2;$i++){$pipes=[];$process=proc_open([PHP_BINARY,'-c',dirname((string)getenv('EVAL_VENDOR_DIR')).'/php.ini',__DIR__.'/activity-race-worker.php',$student->identityId,$race],[0=>['file','NUL','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);if(!is_resource($process))throw new RuntimeException('Race process unavailable');$workers[]=[$process,$pipes];}
